import numpy as np, time
from gri_bench.api import load_instance, Experiment
inst = load_instance()
e = Experiment(inst)
def ev(p):
    return e.evaluate({'mode':'responsive','parameters':{k:float(v) for k,v in zip(['theta_a','relative_leak','ec50_mg_dl','hill_n','tau_min','theta_L'],p)}})

# coarse grid
best=[]
for theta_a in [0.0002,0.0004,0.0006,0.0008]:
  for rl in [0.6,1.0,1.5,2.5]:
    for ec50 in [120,160,200]:
      for hn in [1.5,2.5,3.5]:
        for tau in [5,10,15]:
          for tL in [0.8,1.2,1.6,2.0]:
            m=ev([theta_a,rl,ec50,hn,tau,tL])
            if m['feasible']: best.append((m['mean_tir'],[theta_a,rl,ec50,hn,tau,tL],m))
best.sort(reverse=True)
print('feasible count',len(best))
for v,p,m in best[:15]: print(v,p,m['max_trajectory_tbr70'],m['max_trajectory_tbr54'],m['minimum_glucose'])
